/* Cloudflare email-decode replacement (local, offline build)
 * Decodes Cloudflare-protected email links (<a data-cfemail="..."> and
 * <a href="#<hex>"> produced from /cdn-cgi/l/email-protection links) and
 * turns them into working mailto: links. Algorithm is the standard
 * Cloudflare XOR decode: first byte is the key.
 */
(function () {
  "use strict";
  function decodeHex(hex) {
    var key = parseInt(hex.substring(0, 2), 16);
    var out = "";
    for (var i = 2; i < hex.length; i += 2) {
      out += String.fromCharCode(parseInt(hex.substring(i, i + 2), 16) ^ key);
    }
    return out;
  }
  function fix(a) {
    var hex = a.getAttribute("data-cfemail");
    if (!hex) {
      var m = (a.getAttribute("href") || "").match(/^#([0-9a-fA-F]{16,})$/);
      if (m) hex = m[1];
    }
    if (!hex || !/^[0-9a-fA-F]+$/.test(hex)) return;
    var email = decodeHex(hex.toLowerCase());
    a.setAttribute("href", "mailto:" + email);
    a.removeAttribute("data-cfemail");
    if (a.classList) a.classList.remove("__cf_email__");
    var text = a.textContent || "";
    if (!text || text.indexOf("[email") === 0 || text.indexOf(".") === 0) {
      a.textContent = email;
    }
  }
  function run() {
    var nodes = document.querySelectorAll("[data-cfemail]");
    for (var i = 0; i < nodes.length; i++) fix(nodes[i]);
    nodes = document.querySelectorAll('a[href^="#"]');
    for (var j = 0; j < nodes.length; j++) fix(nodes[j]);
  }
  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", run);
  } else {
    run();
  }
})();
